CONNECT auth_user1/Auth123456@localhost:1521/AUTHPDB1
-- -- Advance sequences past inserted IDs
DECLARE
  PROCEDURE adv(p_seq VARCHAR2, p_target NUMBER) AS
    v NUMBER; d NUMBER;
  BEGIN
    EXECUTE IMMEDIATE 'SELECT ' || p_seq || '.NEXTVAL FROM DUAL' INTO v;
    d := p_target - v;
    IF d > 0 THEN
      EXECUTE IMMEDIATE 'ALTER SEQUENCE ' || p_seq || ' INCREMENT BY ' || d;
      EXECUTE IMMEDIATE 'SELECT ' || p_seq || '.NEXTVAL FROM DUAL' INTO v;
      EXECUTE IMMEDIATE 'ALTER SEQUENCE ' || p_seq || ' INCREMENT BY 1';
    END IF;
  END;
BEGIN
  adv('SEQ_AUTH_ROLE',           7);
  adv('SEQ_AUTH_THEME',          2);
  adv('SEQ_AUTH_METHOD',         4);
  adv('SEQ_AUTH_DEPARTMENT',    59);
